/// <summary>
/// User callable query range functions. A user types "(conDemoNotBlocked())" into any filter field
/// and the platform calls the method to produce the range value.
/// </summary>
[ExtensionOf(classStr(SysQueryRangeUtil))]
public static class ConDemoRangesCon_Extension
{
}

Method.Source:
/// <summary>
/// Builds a range value that matches everything except customers blocked for all activity.
/// </summary>
/// <returns>The negated range expression for <c>CustVendorBlocked::All</c>.</returns>
[QueryRangeFunction()]
public static str conDemoNotBlocked()
{
    return SysQuery::valueNot(CustVendorBlocked::All);
}

/// <summary>
/// Builds a range value covering the current month.
/// </summary>
/// <returns>The range expression from the first to the last day of the current month.</returns>
[QueryRangeFunction()]
public static str conDemoCurrentMonth()
{
    date today;

    today = DateTimeUtil::date(DateTimeUtil::utcNow());

    return SysQuery::range(mkDate(1, mthOfYr(today), year(today)), endmth(today));
}
